from pathlib import Path
import base64, gzip, subprocess, sys

payload = ''
patch = gzip.decompress(base64.b64decode(payload))
proc = subprocess.run(['patch','-p2','--batch','--forward'], input=patch, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
print(proc.stdout.decode('utf-8', errors='replace'))
if proc.returncode != 0:
    raise SystemExit(proc.returncode)
print('alpha.6: binder hover filters, readable cards, MiMi reveal/wander, shop quantities/colors, protected machines')
